WITH valid AS (SELECT id, email, country, city, signup_date, is_active, credit_limit, credit_limit * age credit_limit_times_age FROM customers WHERE signup_date > DATE '2023-06-22'), with_windows AS (SELECT *, ROUND(credit_limit / SUM(credit_limit) OVER (PARTITION BY city, country), 4) credit_limit_share, CUME_DIST() OVER (ORDER BY credit_limit_times_age DESC NULLS LAST) credit_limit_times_age_cume_dist, NTILE(4) OVER (PARTITION BY city ORDER BY credit_limit_times_age DESC, id) credit_limit_times_age_bucket FROM valid WHERE city != 'Singapore'), filtered AS (SELECT *, ROUND(credit_limit, 2) credit_limit_rounded FROM with_windows WHERE NOT is_active), eligible AS (SELECT s.* FROM filtered s WHERE EXISTS (SELECT 1 FROM orders ch WHERE ch.customer_id = s.id AND ch.order_date < s.signup_date)) SELECT id, email, country, city, is_active, credit_limit, credit_limit_times_age_cume_dist, credit_limit_rounded FROM eligible ORDER BY credit_limit DESC NULLS FIRST;
